{"sql":"CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT AS $$
DECLARE
    source_qty INTEGER;
    target_qty INTEGER;
BEGIN
    -- Lock source and target inventories to avoid race conditions
    PERFORM 1 FROM lego_inventories WHERE id = source_inventory_id FOR UPDATE;
    PERFORM 1 FROM lego_inventories WHERE id = target_inventory_id FOR UPDATE;

    -- Validation A: Basic Checks
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = source_inventory_id) THEN
        RAISE EXCEPTION 'Source inventory ID % does not exist', source_inventory_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = target_inventory_id) THEN
        RAISE EXCEPTION 'Target inventory ID % does not exist', target_inventory_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) THEN
        RAISE EXCEPTION 'Part number % does not exist', part_to_transfer_num;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id) THEN
        RAISE EXCEPTION 'Color ID % does not exist', color_to_transfer_id;
    END IF;

    IF source_inventory_id = target_inventory_id THEN
        RAISE EXCEPTION 'Source and target inventories cannot be the same';
    END IF;

    -- Check source quantity for non-spare row
    SELECT quantity INTO source_qty
    FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
    AND part_num = part_to_transfer_num
    AND color_id = color_to_transfer_id
    AND is_spare = false
    FOR UPDATE;

    IF source_qty IS NULL THEN
        RAISE EXCEPTION 'No non-spare parts % with color % found in source inventory %', part_to_transfer_num, color_to_transfer_id, source_inventory_id;
    END IF;

    -- Validation B: Business Rules
    IF quantity_to_transfer < 1 THEN
        RAISE EXCEPTION 'Transfer quantity must be at least 1';
    END IF;
    IF quantity_to_transfer > 500 THEN
        RAISE EXCEPTION 'Transfer quantity must not exceed 500';
    END IF;

    IF source_qty < quantity_to_transfer THEN
        RAISE EXCEPTION 'Insufficient quantity in source inventory: available %, requested %', source_qty, quantity_to_transfer;
    END IF;

    -- Step B: Source Inventory Update
    UPDATE lego_inventory_parts
    SET quantity = quantity - quantity_to_transfer
    WHERE inventory_id = source_inventory_id
    AND part_num = part_to_transfer_num
    AND color_id = color_to_transfer_id
    AND is_spare = false;

    -- Delete row if quantity is zero
    DELETE FROM lego_inventory_parts
    WHERE inventory_id = source_inventory_id
    AND part_num = part_to_transfer_num
    AND color_id = color_to_transfer_id
    AND is_spare = false
    AND quantity = 0;

    -- Step C: Target Inventory Update
    SELECT quantity INTO target_qty
    FROM lego_inventory_parts
    WHERE inventory_id = target_inventory_id
    AND part_num = part_to_transfer_num
    AND color_id = color_to_transfer_id
    AND is_spare = false
    FOR UPDATE;

    IF target_qty IS NULL THEN
        -- Insert new row
        INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, false);
    ELSE
        -- Update existing row
        UPDATE lego_inventory_parts
        SET quantity = quantity + quantity_to_transfer
        WHERE inventory_id = target_inventory_id
        AND part_num = part_to_transfer_num
        AND color_id = color_to_transfer_id
        AND is_spare = false;
    END IF;

    -- Step D: Audit Logging
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success', NULL
    );

    RETURN FORMAT('Successfully transferred % parts (%s, color_id: %) from inventory % to inventory %. Reason: %',
                    quantity_to_transfer, part_to_transfer_num, color_to_transfer_id, source_inventory_id, target_inventory_id, transfer_reason);

EXCEPTION WHEN OTHERS THEN
    -- Log failure
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id, quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', SQLERRM
    );
    RAISE;
END;
$$ LANGUAGE plpgsql;"}
